mapper.select:
SELECT * FROM skill_config WHERE 
ORDER BY created_at DESC, skill_id DESC
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT skill_id, name, description, version, tenant_id, created_by, enabled, api_url, api_headers, prompt_template, steps, tool_dependencies, private_skill, review_status FROM skill_config WHERE (tenant_id = #{tenantId} OR tenant_id = 'default') AND skill_id > #{after}
AND (LOCATE(LOWER(#{query}), LOWER(COALESCE(name, ''))) > 0 OR LOCATE(LOWER(#{query}), LOWER(COALESCE(description, ''))) > 0 OR LOCATE(LOWER(#{query}), LOWER(CONCAT('skill:', skill_id))) > 0)
ORDER BY skill_id ASC LIMIT #{limit}
